/** Verified map ids, e.g. ["oregon","consulate"]. */
export const VERIFIED_MAPS = Object.keys(VERIFIED_MAP_META);

/** True when this map has any verified setup at all. */
export function hasVerifiedSetups(mapId) {
  return VERIFIED_MAPS.includes(mapId);
}

/** Every verified site for a map: [{ key, siteId, label, attack, defense }]. */
export function setupsForMap(mapId) {
  return Object.entries(VERIFIED_SETUPS)
    .filter(([k]) => k.startsWith(mapId + ':'))
    .map(([k, v]) => ({ key: k, siteId: k.split(':')[1], ...v }));
}

/** One site, or null. */
export function setupFor(mapId, siteId) {
  return VERIFIED_SETUPS[mapId + ':' + siteId] || null;
}

export default VERIFIED_SETUPS;
